// +kubebuilder:validation:Enum=small;medium;large
type Size string

type DatabaseSpec struct {
    Size Size `json:"size"`
    // +kubebuilder:validation:Minimum=1
    Replicas int32 `json:"replicas"`
}

// +kubebuilder:rbac:groups=apps,resources=statefulsets,verbs=get;list;watch;create;update;patch

func (r *DatabaseReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    var db datav1.Database
    if err := r.Get(ctx, req.NamespacedName, &db); err != nil {
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }
    sts := &appsv1.StatefulSet{ObjectMeta: metav1.ObjectMeta{Name: db.Name, Namespace: db.Namespace}}
    _, err := controllerutil.CreateOrUpdate(ctx, r.Client, sts, func() error {
        sts.Spec.Replicas = &db.Spec.Replicas
        return controllerutil.SetControllerReference(&db, sts, r.Scheme)
    })
    return ctrl.Result{RequeueAfter: 5 * time.Minute}, err
}

var svc corev1.Service
err := r.Get(ctx, types.NamespacedName{Name: db.Name, Namespace: db.Namespace}, &svc)
if apierrors.IsNotFound(err) {
    return ctrl.Result{}, r.Create(ctx, desiredService(&db))
} else if err != nil {
    return ctrl.Result{}, err
}

bucket := fmt.Sprintf("db-backups-%s", db.UID)
if db.Status.BucketName == "" {
    if err := s3.EnsureBucket(ctx, bucket); err != nil { return ctrl.Result{}, err }
    db.Status.BucketName = bucket
    return ctrl.Result{}, r.Status().Update(ctx, &db)
}

meta.SetStatusCondition(&db.Status.Conditions, metav1.Condition{
    Type: "Ready", Status: metav1.ConditionFalse,
    Reason: "ReplicasNotReady", Message: "2/3 replicas ready",
    ObservedGeneration: db.Generation,
})
return ctrl.Result{RequeueAfter: 30 * time.Second}, r.Status().Update(ctx, &db)

const fin = "data.example.com/cleanup"
if db.DeletionTimestamp.IsZero() {
    if controllerutil.AddFinalizer(&db, fin) { return ctrl.Result{}, r.Update(ctx, &db) }
} else {
    if err := r.deleteCloudDB(ctx, &db); err != nil { return ctrl.Result{}, err }
    controllerutil.RemoveFinalizer(&db, fin)
    return ctrl.Result{}, r.Update(ctx, &db)
}
